<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { canGovernance as can } from '../../governance/permissions.js'
import { createClientId } from '../../clientId.js'
import { governanceRead, governanceWrite } from '../../governance/api.js'
import { activeRun, conflictMessage, label, numericMetric, outputRows, time, tone } from '../../governance/helpers.js'
const props=defineProps({run:Object,devices:Array,readOnly:Boolean})
const emit=defineEmits(['candidate','navigate','adopt','snapshot','refresh'])
const loading=ref(false),error=ref(''),snapshot=ref(null),metrics=ref([]),findings=ref([]),activityCandidates=ref([]),evidence=ref([]),totals=ref({}),moreBusy=ref(''),aiJobs=ref([]),aiId=ref(''),aiBusy=ref(false),aiError=ref(''),useKnowledge=ref(false),factDialog=ref(false),fact=ref(null),findingPage=ref(1)
const ai=computed(()=>aiJobs.value.find(row=>row.id===aiId.value)||aiJobs.value[0]), statistics=computed(()=>snapshot.value?.statistics||{})
const findingsPage=computed(()=>findings.value.slice((findingPage.value-1)*20,findingPage.value*20))
const deviceName=id=>props.devices.find(row=>row.id===id)?.name||id
const sections=[['facts','固定事实'],['patterns','可见模式'],['hypotheses','候选解释'],['checks','待核查问题'],['measures','措施建议'],['observation','观察建议'],['limitations','解读限制']]
let generation=0,timer=0,disposed=false
function stop(){clearTimeout(timer);timer=0}
async function loadAI(token=generation){try{const result=await governanceRead('runs',props.run.id,'ai-jobs');if(token!==generation||disposed)return;aiJobs.value=(result.items||[]).sort((a,b)=>b.createdAt-a.createdAt);if(!aiJobs.value.some(row=>row.id===aiId.value))aiId.value=aiJobs.value[0]?.id||'';stop();if(aiJobs.value.some(activeRun))timer=setTimeout(()=>loadAI(token),2000)}catch(cause){if(token===generation&&!disposed){aiError.value=cause.message;stop()}}}
async function load(){const token=++generation;stop();loading.value=true;error.value='';snapshot.value=null;metrics.value=[];findings.value=[];activityCandidates.value=[];evidence.value=[];aiJobs.value=[];aiId.value='';aiError.value='';findingPage.value=1;if(!props.run?.snapshotId||activeRun(props.run)){loading.value=false;return}try{const results=await Promise.allSettled(['snapshot','metrics','findings','evidence','activity-candidates'].map(operation=>governanceRead('runs',props.run.id,operation,{limit:100})));if(token!==generation||disposed)return;results.forEach((result,index)=>{if(result.status==='rejected'){error.value=result.reason.message;return}const value=result.value;if(index===0){snapshot.value=value;emit('snapshot',value)}else{const operation=['','metrics','findings','evidence','activity-candidates'][index];totals.value[operation]=value.total??value.items?.length??0;if(index===1)metrics.value=outputRows(value.items||[]);else if(index===2)findings.value=outputRows(value.items||[]);else if(index===3)evidence.value=value.items||[];else activityCandidates.value=outputRows(value.items||[])}});if(!props.readOnly)await loadAI(token)}finally{if(token===generation)loading.value=false}}
async function startAI(){if(aiBusy.value||!can('POST /api/v1/alarm-governance/runs/:id/ai-jobs'))return;const token=generation;aiBusy.value=true;aiError.value='';try{const current=await governanceRead('runs',props.run.id);await governanceWrite('runs',props.run.id,'ai-jobs',{expectedVersion:current.version,idempotencyKey:createClientId(),useKnowledge:useKnowledge.value,reinterpret:!!ai.value});if(token===generation&&!disposed)await loadAI(token)}catch(cause){if(token===generation)aiError.value=conflictMessage(cause)}finally{if(token===generation)aiBusy.value=false}}
async function cancelAI(){if(!ai.value||aiBusy.value||!can('POST /api/v1/alarm-governance/runs/:id/ai-jobs/:jobId/stop'))return;aiBusy.value=true;try{await governanceWrite('runs',props.run.id,`ai-jobs/${encodeURIComponent(ai.value.id)}/stop`,{expectedVersion:ai.value.version,idempotencyKey:createClientId()});await loadAI()}catch(cause){aiError.value=cause.message}finally{aiBusy.value=false}}
async function more(operation){if(moreBusy.value)return;const target={metrics,findings,evidence,'activity-candidates':activityCandidates}[operation],token=generation;moreBusy.value=operation;try{const page=await governanceRead('runs',props.run.id,operation,{limit:100,offset:target.value.length});if(token!==generation||disposed)return;target.value.push(...(operation==='evidence'?page.items||[]:outputRows(page.items||[])));totals.value[operation]=page.total??target.value.length}catch(cause){error.value=cause.message}finally{moreBusy.value=''}}
async function showFact(id){let value=evidence.value.find(row=>row.id===id)||metrics.value.find(row=>row.id===id)||findings.value.find(row=>row.id===id);const token=generation;if(!value)try{value=await governanceRead('runs',props.run.id,`facts/${encodeURIComponent(id)}`);if(token!==generation||disposed)return;if(value.id!==id)throw new Error('返回事实身份与当前固定引用不一致')}catch(cause){if(token===generation&&!disposed){aiError.value=cause.message;error.value=cause.message}return}fact.value=value;factDialog.value=true}
async function showMetric(id){let value=metrics.value.find(row=>row.id===id);const token=generation;if(!value)try{for(let offset=100;;offset+=100){const page=await governanceRead('runs',props.run.id,'metrics',{limit:100,offset});if(token!==generation||disposed)return;const rows=outputRows(page.items||[]);value=rows.find(row=>row.id===id);if(value||!rows.length||offset+rows.length>=(page.total??offset+rows.length))break}}catch(cause){aiError.value=cause.message;return}if(!value){aiError.value='该数字引用未匹配当前快照中的固定指标；请核对原始证据。';return}fact.value=value;factDialog.value=true}
watch(()=>[props.run?.id,props.run?.snapshotId],load,{immediate:true});onBeforeUnmount(()=>{disposed=true;generation++;stop()})
</script>
<template><section class="gov-stack"><ui-skeleton v-if="loading" :rows="5"/><ui-alert v-if="error" :title="error" type="error" :closable="false"><ui-button size="small" @click="load">重新读取固定结果</ui-button></ui-alert><template v-if="snapshot"><div class="gov-card"><h3>固定事实与覆盖</h3><p class="gov-meta">快照 {{snapshot.id}} · 版本 {{snapshot.version}} · 资料版本 {{statistics.dataRevision??'未知'}} · 事实 {{snapshot.factsHash||'未返回'}}</p><p v-for="reason in [...(snapshot.limitations||[]),...(statistics.limits||[])]" :key="reason" class="gov-meta">{{label(reason)}}</p><p v-if="snapshot.missingSources?.length" class="gov-meta">缺失来源：{{snapshot.missingSources.join('、')}}</p><p v-if="snapshot.uncomputableMetrics?.length" class="gov-meta">不可计算：{{snapshot.uncomputableMetrics.join('、')}}</p><p class="gov-meta">指标使用逐次合法源身份；生产告警累计次数、人工确认或关闭不替代信号周期。</p></div><div class="gov-cards"><article v-for="row in metrics" :key="row.id||JSON.stringify(row.point)+row.period" class="gov-card"><h3>{{deviceName(row.point?.deviceId||row.deviceId)}} · {{row.point?.componentId||'设备'}} · {{row.point?.alarmType}} · {{row.period==='BEFORE'?'改善前':row.period==='AFTER'?'改善后':'当前窗口'}}</h3><div class="gov-metrics"><div><span>原始上报</span><strong>{{numericMetric(row.reportCount)}}</strong></div><div><span>可靠新开始</span><strong>{{row.cycleMethod==='REPORT_ONLY'?'不可计算':numericMetric(row.knownStarts)}}</strong></div><div><span>未明确恢复</span><strong>{{row.cycleMethod==='REPORT_ONLY'?'不可计算':numericMetric(row.openCycles)}}</strong></div><div><span>边界未知</span><strong>{{row.cycleMethod==='REPORT_ONLY'?'不可计算':numericMetric(row.boundaryUnknown)}}</strong></div></div><p class="gov-meta">信号 {{row.point?.signalKey}} · 来源 {{label(row.point?.originKind)}} · {{label(row.cycleMethod||row.cycles?.[0]?.method)}}</p><p class="gov-meta">核实记录 {{numericMetric(row.verificationCount)}} · 未核实 {{numericMetric(row.unverifiedCount)}} · 每千小时可靠新开始 {{row.cycleMethod==='REPORT_ONLY'?'不可计算':numericMetric(row.newStartsPer1000Hours)}}</p><p v-for="reason in row.limitations||[]" :key="reason" class="gov-meta">{{label(reason)}}</p><template v-if="row.activity"><p>合格实际活动 N={{row.activity.n??'未知'}} · 已确认相关 C={{row.activity.c??'未知'}} · 未核实/有争议 U={{row.activity.u??'未知'}}</p><p class="gov-meta">已确认不相关 {{row.activity.verifiedUnrelated??'未知'}} · 未记录报警 {{row.activity.noRecordedAlarm??'未知'}} · 不符合准入 {{row.activity.ineligible??'未知'}}</p><p>相关活动比例 {{row.activity.relatedFraction==null?'不可计算':(Number(row.activity.relatedFraction)*100).toFixed(1)+'%'}} · 识别区间 {{Array.isArray(row.activity.identificationInterval)?row.activity.identificationInterval.map(value=>(value*100).toFixed(1)+'%').join(' ～ '):'不可计算'}}</p><p class="gov-meta">有效监测 {{numericMetric(row.activity.effectiveMonitoringHours)}} 小时 · {{label(row.activity.coverage)}}。识别区间说明未核实事件归属，不是统计置信区间。</p><p v-for="reason in row.activity.limitations||[]" :key="reason" class="gov-meta">{{label(reason)}}</p></template><details v-if="row.cycles?.length"><summary>周期成员与边界</summary><article v-for="cycle in row.cycles" :key="cycle.id" class="gov-card"><strong>{{label(cycle.status)}} · {{label(cycle.boundaryQuality)}}</strong><p class="gov-meta">{{time(cycle.startAt||cycle.startedAt)}} ～ {{time(cycle.endAt||cycle.endedAt)}} · 成员 {{cycle.observationIds?.length||cycle.memberIds?.length||0}} 条</p></article></details></article></div><ui-button v-if="metrics.length<totals.metrics" size="small" :loading="moreBusy==='metrics'" @click="more('metrics')">加载更多固定指标（{{metrics.length}} / {{totals.metrics}}）</ui-button><ui-alert v-if="statistics.comparison" :title="label(statistics.comparison.conclusion)" type="warning" :closable="false"><p v-for="reason in statistics.comparison.limitations||[]" :key="reason">{{label(reason)}}</p><p v-if="statistics.comparison.difference!=null">可比较变化 {{statistics.comparison.difference}}</p></ui-alert><details v-if="activityCandidates.length"><summary>实际活动候选（{{activityCandidates.length}} 条线索，未确认归属）</summary><article v-for="row in activityCandidates" :key="row.id" class="gov-card"><strong>{{deviceName(row.point?.deviceId)}} · {{row.activityType}}</strong><p class="gov-meta">事件 {{row.observationId}} · 实际活动 {{row.activityId}} · 固定记录 {{row.activityRevisionId}} · {{time(row.startAt)}} ～ {{time(row.endAt)}}</p><p class="gov-meta">实际区间重叠保留全部候选；现场核实需要人工选择归属，不自动确认活动相关。</p></article></details><ui-button v-if="activityCandidates.length<totals['activity-candidates']" size="small" :loading="moreBusy==='activity-candidates'" @click="more('activity-candidates')">加载更多活动候选（{{activityCandidates.length}} / {{totals['activity-candidates']}}）</ui-button><h3 v-if="!readOnly">确定性问题发现</h3><div class="gov-cards"><article v-for="row in findingsPage" :key="row.id" class="gov-card"><strong>{{deviceName(row.point?.deviceId||row.deviceId)}} · {{row.point?.alarmType}}</strong><p>{{(row.conditions||[]).map(item=>label(typeof item==='string'?item:item.description||item.kind)).join('；')}}</p><p class="gov-meta">{{time(row.window?.start)}} ～ {{time(row.window?.end)}} · 策略版本 {{row.policyVersion||'未知'}} · {{label(row.coverage)}} · 具体事件 {{row.observationIds?.length||0}} 条</p><ui-button v-if="!readOnly&&can('POST /api/v1/alarm-governance/cases')" size="small" @click="emit('candidate',row)">{{row.existingCaseId?'查看或追加已有事项':'人工建立事项'}}</ui-button></article></div><ui-empty v-if="!findings.length" description="本快照没有命中问题发现条件；同时核对历史覆盖与不可计算项。"/><ui-pagination :current-page="findingPage" :page-size="20" :total="findings.length" @current-change="findingPage=$event"/>
<ui-button v-if="findings.length<totals.findings" size="small" :loading="moreBusy==='findings'" @click="more('findings')">加载更多问题（{{findings.length}} / {{totals.findings}}）</ui-button><details><summary>固定证据（已载入 {{evidence.length}} / {{totals.evidence||0}}）</summary><article v-for="row in evidence" :key="row.id" class="gov-card"><p>{{row.summary?.description||row.summary?.text||row.sourceType}} · {{row.sourceId}}</p><ui-button text size="small" @click="showFact(row.id)">查看固定引用</ui-button></article><ui-button v-if="evidence.length<totals.evidence" size="small" :loading="moreBusy==='evidence'" @click="more('evidence')">加载更多证据</ui-button></details><div v-if="!readOnly" class="gov-card gov-stack"><div class="gov-toolbar"><h3>AI 解读</h3><div class="gov-actions"><ui-button v-if="can('POST /api/v1/alarm-governance/runs/:id/ai-jobs')" size="small" :loading="aiBusy" :disabled="aiJobs.some(activeRun)" @click="startAI">{{ai?'重新解读':'开始解读'}}</ui-button><ui-button v-if="ai&&activeRun(ai)&&can('POST /api/v1/alarm-governance/runs/:id/ai-jobs/:jobId/stop')" size="small" :loading="aiBusy" @click="cancelAI">停止解读</ui-button></div></div><p class="gov-meta">仅由按钮启动。候选解释不会自动成为成因或下一次现场结论；人工输入独立保留。</p><ui-checkbox v-if="can('POST /api/v1/alarm-governance/runs/:id/ai-jobs')" v-model="useKnowledge">使用本工作流已授权知识</ui-checkbox><ui-alert v-if="aiError" :title="aiError" type="warning" :closable="false"/><ui-select v-if="aiJobs.length>1" v-model="aiId"><ui-option v-for="job in aiJobs" :key="job.id" :value="job.id" :label="`${time(job.createdAt)} · ${label(job.status)} · 快照 ${job.snapshotVersion}`"/></ui-select><template v-if="ai"><ui-tag :type="tone(ai.status)">{{label(ai.status)}}</ui-tag><p v-if="ai.error" class="gov-meta">{{ai.error}}；事实与人工治理仍可使用。</p><p class="gov-meta">模型 {{ai.model||'由工作流配置'}} · 读取事实 {{ai.factIds?.length||0}} 条 · {{ai.coverage?.summary||'覆盖以固定引用为准'}}</p><p>{{ai.interpretation?.summary}}</p><section v-for="[key,title] in sections" v-show="ai.interpretation?.[key]?.length" :key="key"><h4>{{title}}</h4><article v-for="(item,index) in ai.interpretation?.[key]||[]" :key="index" class="gov-card"><p>{{typeof item==='string'?item:item.text||item.explanation}}</p><div class="gov-actions"><ui-button v-for="id in item.factIds||[]" :key="id" text size="small" @click="showFact(id)">证据 {{id}}</ui-button><ui-button v-if="key==='hypotheses'&&can('POST /api/v1/alarm-governance/rounds/:id/causes')" text size="small" @click="emit('adopt',item)">带入人工候选原因表单</ui-button></div><div v-if="item.metricRefs?.length" class="gov-actions"><ui-button v-for="id in item.metricRefs" :key="id" text size="small" @click="showMetric(id)">固定指标 {{id}}</ui-button></div></article></section></template><ui-empty v-else description="尚未手动启动 AI 解读。"/></div></template><ui-empty v-else-if="!loading&&!activeRun(run)" description="尚无固定快照，请核对任务错误或重新计算。"/></section><ui-dialog v-model="factDialog" title="固定证据引用" width="min(740px,94vw)"><div class="gov-dialog-body"><template v-if="fact?.point&&fact?.period"><h3>{{deviceName(fact.point.deviceId)}} · {{fact.point.alarmType}} · {{fact.period==='BEFORE'?'改善前':fact.period==='AFTER'?'改善后':'当前窗口'}}</h3><p class="gov-meta">{{time(fact.window?.start)}} ～ {{time(fact.window?.end)}} · {{label(fact.cycleMethod)}} · 固定单位与分母来自服务端快照</p><div class="gov-metrics"><div><span>去重上报（条）</span><strong>{{numericMetric(fact.reportCount)}}</strong></div><div><span>可靠新开始（个）</span><strong>{{fact.cycleMethod==='REPORT_ONLY'?'不可计算':numericMetric(fact.knownStarts)}}</strong></div><div><span>合格活动分母 N（次）</span><strong>{{numericMetric(fact.activity?.n)}}</strong></div><div><span>已确认相关分子 C（次）</span><strong>{{numericMetric(fact.activity?.c)}}</strong></div><div><span>有效监测（小时）</span><strong>{{numericMetric(fact.activity?.effectiveMonitoringHours)}}</strong></div><div><span>服务端相关比例 C/N</span><strong>{{fact.activity?.relatedFraction==null?'不可计算':(fact.activity.relatedFraction*100).toFixed(1)+'%'}}</strong></div></div><p v-for="reason in [...(fact.limitations||[]),...(fact.activity?.limitations||[])]" :key="reason" class="gov-meta">{{label(reason)}}</p></template><p>{{fact?.summary?.description||fact?.explanation||fact?.summary?.text}}</p><p class="gov-meta">固定身份 {{fact?.id}} · 原来源 {{fact?.sourceId}} · {{fact?.sourceType}}</p><pre class="gov-fact">{{JSON.stringify(fact?.summary||fact?.body||fact,null,2)}}</pre><ui-button v-if="(fact?.rawMessageId||fact?.summary?.rawMessageId)&&can('menu:raw')" size="small" @click="emit('navigate','raw',{deviceId:fact.deviceId,rawMessageId:fact.rawMessageId||fact.summary.rawMessageId})">授权查看原文</ui-button></div></ui-dialog>
</template>
